"use strict";(globalThis.webpackChunkgrc||=[]).push([[35601],{10473(e){e.exports=JSON.parse('[{"citeKey":"hu2026datareuse","slug":"hu-2026-improving-data-reuse-3e1f","title":"Improving Data Reuse across Blocks for Efficient Block-Sparse Transformers on GPUs","authors":["L. Hu","X. Lu","X.-H. Sun","P. Jiang"],"venue":"35th International Conference on Parallel Architectures and Compilation Techniques (PACT 2026)","type":"Conference","entryType":"inproceedings","date":"October, 2026","year":2026,"era":"iit","month":10,"hasAbstract":false,"links":{"program":"https://pact2026.github.io/program/#papers"},"tags":["Block-Sparse Transformers","GPU Acceleration","Data Reuse","Sparse Computing"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"lu2026ioaware","slug":"lu-2026-io-aware-ri45","title":"I/O-Aware PIM Acceleration for Long-Sequence LLM Inference with Hybrid Sparse Attention","authors":["X. Lu","L. Hu","H. Huang","P. Jiang","X.-H. Sun"],"venue":"Proceedings of the 40th IEEE International Parallel and Distributed Processing Symposium (IPDPS 2026)","type":"Conference","entryType":"inproceedings","date":"May, 2026","year":2026,"era":"iit","month":5,"doi":"10.1109/IPDPS65963.2026.00046","hasAbstract":false,"pages":"445\u2013457","links":{"pdf":"https://grc.iit.edu/papers/2026/lu-2026-io-aware-ri45.pdf","bibtex":"https://grc.iit.edu/papers/2026/lu-2026-io-aware-ri45-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/lu-2026-io-aware-ri45-citation.txt"},"tags":["I/O Analysis","Hardware/Software Co-Design","PIM","UniMCC"],"_projectIds":["unimcc"],"_funding":[{"agency":"NSF","award":"CNS-2310422","agencyKnown":true},{"agency":"NSF","award":"CNS-2152497","agencyKnown":true},{"agency":"NSF","award":"CNS-2310423","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"wu2026hypim","slug":"wu-2026-hypim-c05e","title":"HyPIM: Accelerating Hyperbolic Machine Learning via Processing-In-Memory","authors":["J. Wu","F. Ozdaban","S. Sadhasivam","X. Lu","Y. Guo","M. Zhou"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/Wu_Jinlin_HyPIM%20-%20Jinlin%20Wu.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"biryukov2026zion","slug":"biryukov-2026-zion-a1b2","title":"Zion: A Comprehensive, Adaptive, and Lightweight Hardware Prefetcher","authors":["V. Biryukov","X. Lu","Z. Liu","K. Zhou","X.-H. Sun"],"venue":"Proceedings of the 2026 Design, Automation and Test in Europe Conference (DATE 2026)","type":"Conference","entryType":"inproceedings","date":"April, 2026","year":2026,"era":"iit","month":4,"doi":"10.23919/DATE69613.2026.11539299","hasAbstract":false,"pages":"1\u20137","links":{"pdf":"https://grc.iit.edu/papers/2026/biryukov-2026-zion-a1b2.pdf","bibtex":"https://grc.iit.edu/papers/2026/biryukov-2026-zion-a1b2-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/biryukov-2026-zion-a1b2-citation.txt"},"tags":["Hardware Prefetcher","Memory System Optimization","UniMCC"],"_projectIds":["unimcc"],"_funding":[{"agency":"NSF","award":"CNS-2310422","agencyKnown":true},{"agency":"NSF","award":"CNS-2152497","agencyKnown":true},{"agency":"NSF","award":"CNS-2431516","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lu2026ioanalysis","slug":"lu-2026-io-analysis-b2c3","title":"I/O Analysis is All You Need: An I/O Analysis for Long-Sequence Attention","authors":["X. Lu","B. Long","X. Chen","Y. Han","X.-H. Sun"],"venue":"Proceedings of the 31st ACM International Conference on Architectural Support for Programming Languages and Operating Systems, Volume 2 (ASPLOS 2026)","type":"Conference","entryType":"inproceedings","date":"March, 2026","year":2026,"era":"iit","month":3,"doi":"10.1145/3779212.3790174","hasAbstract":false,"pages":"962\u2013977","links":{"pdf":"https://grc.iit.edu/papers/2026/lu-2026-io-analysis-b2c3.pdf","bibtex":"https://grc.iit.edu/papers/2026/lu-2026-io-analysis-b2c3-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/lu-2026-io-analysis-b2c3-citation.txt"},"tags":["I/O Analysis","Hardware/Software Co-Design","Accelerator","UniMCC"],"_projectIds":["unimcc"],"_funding":[{"agency":"NSF","award":"CNS-2310422","agencyKnown":true},{"agency":"NSF","award":"CNS-2152497","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"geng2025cosmos","slug":"geng-2025-cosmos-fb4d","title":"COSMOS: RL-Enhanced Locality-Aware Counter Cache Optimization for Secure Memory","authors":["H. Geng","X. Lu","Y. Che","Z. Tian","D. Cheng","X.-H. Sun","M. Niemier","X. Hu"],"venue":"The 58th IEEE/ACM International Symposium on Microarchitecture (MICRO-58)","type":"Conference","entryType":"inproceedings","date":"October, 2025","year":2025,"era":"iit","month":10,"doi":"10.1145/3725843.3756047","hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2025/geng-2025-cosmos-fb4d.pdf"},"tags":["Cache Management","Memory System Optimization"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CNS-2152497","agencyKnown":true},{"agency":"NSF","award":"CNS-2310422","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"wu2025concurrencyaware","slug":"wu-2025-concurrency-aware-42dd","title":"Concurrency-Aware Cache Miss Cost Prediction with Perceptron Learning","authors":["Y. Wu","X. Lu","X. Chen","Y. Han","X.-H. Sun"],"venue":"The 35th ACM Great Lakes Symposium on VLSI (GLSVLSI 2025), New Orleans, LA, USA, June 30 - July 2, 2025","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3716368.3735219","hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2025/wu-2025-concurrency-aware-42dd.pdf"},"tags":["Cache Management","Memory System Optimization","Concurrency"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yan2025prominer","slug":"yan-2025-prominer-7dc6","title":"ProMiner: Enhancing Locality, Parallelism, and Offloading for Graph Mining on Processing-in-Memory Systems","authors":["L. Yan","X. Lu","S. Xu","X. Chen","X. Zou","Y. Han","X.-H. Sun"],"venue":"IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (TCAD)","type":"Journal","entryType":"article","date":"May, 2025","year":2025,"era":"iit","month":5,"doi":"10.1109/TCAD.2025.3570164","hasAbstract":false,"volume":"44","number":"12","pages":"4577\u20134590","links":{"pdf":"https://grc.iit.edu/papers/2025/yan-2025-prominer-7dc6.pdf"},"tags":["Graph Mining","Processing-in-Memory","Hardware Acceleration"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yan2025pyramid","slug":"yan-2025-pyramid-7e42","title":"Pyramid: Accelerating LLM Inference with Cross-Level Processing-in-Memory","authors":["L. Yan","X. Lu","X. Chen","Y. Han","X.-H. Sun"],"venue":"IEEE Computer Architecture Letters (CAL), April 2025","type":"Journal","entryType":"article","date":"April, 2025","year":2025,"era":"iit","month":4,"doi":"10.1109/lca.2025.3559738","hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2025/yan-2025-pyramid-7e42.pdf"},"tags":["LLM Inference","Processing-in-Memory","Hardware Acceleration"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yan2024aceminer","slug":"yan-2024-aceminer-c390","title":"AceMiner: Accelerating Graph Pattern Matching using PIM with Optimized Cache System","authors":["L. Yan","X. Lu","X. Chen","S. Xu","X. Zou","Y. Han","X.-H. Sun"],"venue":"The 2024 IEEE 42nd International Conference on Computer Design (ICCD\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/iccd63220.2024.00091","abstract":"Graph pattern matching (GPM), a critical algorithm for discovering specific patterns within complex structures, is becoming increasingly important in the data-driven world. GPM applications are memory-bound and can be accelerated by memory-centric computing systems, such as processing-in-memory (PIM). However, there are three primary challenges when it comes to accelerating GPM applications with PIM: (1) difficulty in utilizing locality, (2) heavy data movement, and (3) heavy comparison overhead due to pruning. To address these challenges, we propose AceMiner, a framework to accelerate GPM applications with a software and hardware co-design perspective using PIM. In AceMiner, we embed hybridCache, a novel in-DRAM cache system with lower access latency and optimized replacement policy, to leverage the potential locality and reduce data movement in PIM. Additionally, we introduce a comparison unit to address the huge pruning overhead. Experimental results show that AceMiner outperforms the state-of-the-art, achieving speedups of 40.2% and 13.3% over NDMiner and DIMMining respectively, with less energy consumption and design overhead.","hasAbstract":true,"lede":"To address these challenges, we propose AceMiner, a framework to accelerate GPM applications with a software and hardware co-design perspective using PIM.","links":{"pdf":"https://grc.iit.edu/papers/2024/yan-2024-aceminer-c390.pdf","slides":"https://grc.iit.edu/papers/2024/yan-2024-aceminer-c390-slides.pdf"},"tags":["Graph Pattern Matching","Processing-in-Memory","Cache System"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lu2024aces","slug":"lu-2024-aces-6fdd","title":"ACES: Accelerating Sparse Matrix Multiplication with Adaptive Execution Flow and Concurrency-Aware Cache Optimizations","authors":["X. Lu","B. Long","X. Chen","Y. Han","X.-H. Sun"],"venue":"The 29th ACM International Conference on Architectural Support for Programming Languages and Operating Systems (ASPLOS-29)","type":"Conference","entryType":"inproceedings","date":"April, 2024","year":2024,"era":"iit","month":4,"doi":"10.1145/3620666.3651381","abstract":"Sparse matrix-matrix multiplication (SpMM) is a critical com- putational kernel in numerous scientific and machine learn- ing applications. SpMM involves massive irregular memory accesses and poses great challenges to conventional cache- based computer architectures. Recently dedicated SpMM accelerators have been proposed to enhance SpMM per- formance. However, current SpMM accelerators still face challenges in adapting to varied sparse patterns, fully ex- ploiting inherent parallelism, and optimizing cache perfor- mance. To address these issues, we introduce ACES, a novel SpMM accelerator in this study. First, ACES features an adaptive execution flow that dynamically adjusts to diverse sparse patterns. The adaptive execution flow balances par- allel computing efficiency and data reuse. Second, ACES incorporates locality-concurrency co-optimizations within the global cache. ACES utilizes a concurrency-aware cache management policy, which considers data locality and con- currency for optimal replacement decisions. Additionally, the integration of a non-blocking buffer with the global cache en- hances concurrency and reduces computational stalls. Third, the hardware architecture of ACES is designed to integrate all innovations. The architecture ensures efficient support across the adaptive execution flow, advanced cache opti- mizations, and fine-grained parallel processing. Our perfor- mance evaluation demonstrates that ACES significantly out- performs existing solutions, providing a 2.1\xd7 speedup and marking a substantial advancement in SpMM acceleration.","hasAbstract":true,"lede":"To address these issues, we introduce ACES, a novel SpMM accelerator in this study.","links":{"pdf":"https://grc.iit.edu/papers/2024/lu-2024-aces-6fdd.pdf","slides":"https://grc.iit.edu/papers/2024/lu-2024-aces-6fdd-slides.pdf","poster":"https://grc.iit.edu/papers/2024/lu-2024-aces-6fdd-poster.pdf"},"tags":["SpMM","Accelerator","Parallelism","Concurrency","Synchronization","Scalability","UniMCC"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CNS-2310422","agencyKnown":true},{"agency":"NSF","award":"CNS-2152497","agencyKnown":true},{"agency":"NSF","award":"CCF-2029014","agencyKnown":true},{"agency":"NSF","award":"CCF-2008907","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lu2024chrome","slug":"lu-2024-chrome-1321","title":"CHROME: Concurrency-Aware Holistic Cache Management Framework with Online Reinforcement Learning","authors":["X. Lu","H. Najafi","J. Liu","X.-H. Sun"],"venue":"The 30th IEEE International Symposium on High-Performance Computer Architecture (HPCA 2024), Edinburgh, Scotland","type":"Conference","entryType":"inproceedings","date":"March, 2024","year":2024,"era":"iit","month":3,"doi":"10.1109/hpca57654.2024.00090","abstract":"Cache management is a critical aspect of computer architecture, encompassing techniques such as cache replace- ment, bypassing, and prefetching. Existing research has often fo- cused on individual techniques, overlooking the potential benefits of joint optimization. Moreover, many of these approaches rely on static and intuition-driven policies, limiting their performance under complex and dynamic workloads. To address these chal- lenges, this paper introduceesCHROME,a novelty aware cache management framework. CHROME takes a holistic approach by seamlessly integrating intelligent cache replacement and bypassing with pattern-based prefetching. By leveraging online reinforcement learning, CHROME dynamically adapts cache decisions based on multiple program features and applies a reward for each decision that considers the accuracy of the action and the system-level feedback information. Our performance evaluation demonstrates that CHROME outperforms current state-of-the-art schemes, exhibiting significant improvements in cache management. Notably, CHROME achieves a remarkable performance boost of up to 13.7% over the traditional LRU method in multi-core systems with only modest overhead.","hasAbstract":true,"lede":"To address these chal- lenges, this paper introduceesCHROME,a novelty aware cache management framework.","links":{"pdf":"https://grc.iit.edu/papers/2024/lu-2024-chrome-1321.pdf","slides":"https://grc.iit.edu/papers/2024/lu-2024-chrome-1321-slides.pdf"},"tags":["Memory Architecture","Cache Management","Optimization of Memory Architectures","UniMCC"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CCF-2008000","agencyKnown":true},{"agency":"NSF","award":"CNS-1956229","agencyKnown":true},{"agency":"NSF","award":"IIS-2331908","agencyKnown":true},{"agency":"NSF","award":"CNS-2310422","agencyKnown":true},{"agency":"NSF","award":"CNS-2152497","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lu2023care","slug":"lu-2023-care-bc99","title":"CARE: A Concurrency-Aware Enhanced Lightweight Cache Management Framework","authors":["X. Lu","R. Wang","X.-H. Sun"],"venue":"The 29th IEEE International Symposium on High-Performance Computer Architecture (HPCA-29), Montreal, QC, Canada, February 25 - March 01, 2023","type":"Conference","entryType":"inproceedings","date":"February, 2023","year":2023,"era":"iit","month":2,"doi":"10.1109/hpca56546.2023.10071125","abstract":"Improving cache performance is a lasting research topic. While utilizing data locality to enhance cache performance becomes more and more difficult, data access concurrency provides a new opportunity for cache performance optimization. In this work, we propose a novel concurrency-aware cache management framework that outperforms state-of-the-art locality-only cache management schemes. First, we investigate the merit of data access concurrency and pinpoint that reducing the miss rate may not necessarily lead to better overall performance. Next, we introduce the pure miss contribution (PMC) metric, a lightweight and versatile concurrency-aware indicator, to accurately measure the cost of each outstanding miss access by considering data concurrency. Then, we present CARE, a dynamic adjustable, concurrency-aware, low-overhead cache management framework with the help of the PMC metric. We evaluate CARE with extensive experiments across different application domains and show significant performance gains with the consideration of data concurrency. In a 4-core system, CARE improves IPC by 10.3% over LRU replacement. In 8 and 16-core systems where more concurrent data accesses exist, CARE outperforms LRU by 13.0% and 17.1%, respectively.","hasAbstract":true,"lede":"We propose a novel concurrency-aware cache management framework that outperforms state-of-the-art locality-only cache management schemes.","links":{"pdf":"https://grc.iit.edu/papers/2023/lu-2023-care-bc99.pdf","slides":"https://grc.iit.edu/papers/2023/lu-2023-care-bc99-slides.pdf"},"tags":["Optimization of Memory Architectures"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CCF-2029014","agencyKnown":true},{"agency":"NSF","award":"CCF-2008907","agencyKnown":true},{"agency":"NSF","award":"CNS-2152497","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"sun2023memorybounded","slug":"sun-2023-memory-bounded-824c","title":"The Memory-Bounded Speedup Model and Its Impacts in Computing","authors":["X.-H. Sun","X. Lu"],"venue":"Journal of Computer Science and Technology (JCST\'23), vol. 38, no. 1, February 2023","type":"Journal","entryType":"article","date":"February, 2023","year":2023,"era":"iit","month":2,"doi":"10.1007/s11390-022-2911-1","abstract":"With the surge of big data applications and the worsening of the memory-wall problem, the memory system, instead of the computing unit, becomes the commonly recognized major concern of computing. However, this \\"memory- centric\\" common understanding has a humble beginning. More than three decades ago, the memory-bounded speedup model is the first model recognizing memory as the bound of computing and provided a general bound of speedup and a computing-memory trade-off formulation. The memory-bounded model was well received even by then. It was immediate- ly introduced in several advanced computer architecture and parallel computing textbooks in the 1990\'s as a must-know for scalable computing. These include Prof. Kai Hwang\'s book \\"Scalable Parallel Computing\\" in which he introduced the memory-bounded speedup model as the Sun-Ni\'s Law, parallel with the Amdahl\'s Law and the Gustafson\'s Law. Through the years, the impacts of this model have grown far beyond parallel processing and into the fundamental of computing. In this article, we revisit the memory-bounded speedup model and discuss its progress and impacts in depth to make a unique contribution to this special issue, to stimulate new solutions for big data applications, and to promote data-centric think- ing and rethinking.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2023/sun-2023-memory-bounded-824c.pdf"},"tags":["Memory-Bounded Speedup","Scalable Computing","Memory-Wall","Data-Centric Design","Optimization of Memory Architectures"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CCF-2029014","agencyKnown":true},{"agency":"NSF","award":"CCF-2008907","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"najafi2022generalizedmodel","slug":"najafi-2022-generalized-model-3e33","title":"A Generalized Model For Modern Hierarchical Memory System","authors":["H. Najafi","X. Lu","J. Liu","X.-H. Sun"],"venue":"The 2022 Winter Simulation Conference (WSC), Singapore, December 11-14, 2022","type":"Conference","entryType":"inproceedings","date":"December, 2022","year":2022,"era":"iit","month":12,"doi":"10.1109/wsc57314.2022.10015298","abstract":"Memory system is critical to architecture design which can significantly impact application performance. Concurrent Average Memory Access Time (C-AMAT) is a model for analyzing and optimizing memory system performance using a recursive definition of the memory access latency along the memory hierarchy. The original C-AMAT model, however, does not provide the necessary granularity and flexibility for handling modern memory architectures with heterogeneous memory technologies and diverse system topology. We propose to augment C-AMAT to take into consideration the idiosyncrasies of individual cache/memory components as well as their topological arrangement in the memory architecture design. Through trace- based simulation, we validate the augmented model and examine the memory system performance with insight unavailable using the original C-AMAT model.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2022/najafi-2022-generalized-model-3e33.pdf"},"tags":["Hierarchical Memory System","C-AMAT","Optimization of Memory Architectures"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CCF-2008000","agencyKnown":true},{"agency":"NSF","award":"CCF-2008907","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lu2021premier","slug":"lu-2021-premier-10f5","title":"Premier: A Concurrency-Aware Pseudo-Partitioning Framework for Shared Last-Level Cache","authors":["X. Lu","R. Wang","X.-H. Sun"],"venue":"The 2021 IEEE 39th International Conference on Computer Design (ICCD\'21), October 24 - 27, 2021","type":"Conference","entryType":"inproceedings","date":"October, 2021","year":2021,"era":"iit","month":10,"doi":"10.1109/iccd53106.2021.00068","abstract":"As the number of on-chip cores and application de- mands increase, efficient management of shared cache resources becomes imperative. Cache partitioning techniques have been studied for decades to reduce interference between applications in a shared cache and provide performance and fairness guarantees. However, there are few studies on how concurrent memory accesses affect the effectiveness of partitioning. When concurrent memory requests exist, cache miss does not reflect concurrency overlapping well. In this work, we first introduce pure misses per kilo instructions (PMPKI), a metric that quantifies the cache efficiency considering concurrent access activities. Then we propose Premier, a dynamically adaptive concurrency-aware cache pseudo-partitioning framework. Premier provides insertion and promotion policies based on PMPKI curves to achieve the benefits of cache partitioning. Finally, our evaluation of various workloads shows that Premier outperforms state-of-the-art cache partitioning schemes in terms of performance and fairness. In an 8-core system, Premier achieves 15.45% higher system performance and 10.91% better fairness than the UCP scheme.","hasAbstract":true,"lede":"We first introduce pure misses per kilo instructions (PMPKI), a metric that quantifies the cache efficiency considering concurrent access activities.","links":{"pdf":"https://grc.iit.edu/papers/2021/lu-2021-premier-10f5.pdf"},"tags":["Optimization of Memory Architectures"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CCF-2029014","agencyKnown":true},{"agency":"NSF","award":"CCF-2008907","agencyKnown":true},{"agency":"NSF","award":"CNS-1730488","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yan2021copim","slug":"yan-2021-copim-a500","title":"CoPIM: A Concurrency-aware PIM Workload Offloading Architecture for Graph Applications","authors":["L. Yan","M. Zhang","R. Wang","X. Chen","X. Zou","X. Lu","Y. Han","X.-H. Sun"],"venue":"The 2021 ACM/IEEE International Symposium on Low Power Electronics and Design (ISLPED\'21), July 26, 2021","type":"Conference","entryType":"inproceedings","date":"July, 2021","year":2021,"era":"iit","month":7,"doi":"10.1109/islped52811.2021.9502483","abstract":"Processing-in-Memory (PIM) is considered a promising solution to improve the performance of graph- computing applications by minimizing the data movement be- tween the host and memory. Which workload to offload and how to offload it to PIM logic determine whether the PIM architecture is well utilized. Offloading too much or too little workload from the host processor to the PIM side could hurt overall performance. On the other hand, the offloading granularity needs to be representative without losing generality. In this paper, we present CoPIM, a novel PIM workload offloading architecture that can dynamically determine which portion of the graph workload can benefit more from PIM-side computation. COPIM focuses on the loop code blocks of graph applications and evaluates the necessity of offloading based on a concurrent memory access model. We also provide detailed architectural designs to support the offloading. In this way, CoPIM reduces the size of offloading instructions and also improves the overall performance with less energy consumption. The experimental results show that compared with other state-of-the-art PIM workload offloading frameworks, CoPIM achieves a speedup by the geometric mean of 19.5% and 11.4% than PEI and GraphPIM, respectively. On the other hand, CoPIM also reduces the un-core energy consumption by 6.8% and 6.5% on average over PEI and GraphPIM, respectively.","hasAbstract":true,"lede":"We present CoPIM, a novel PIM workload offloading architecture that can dynamically determine which portion of the graph workload can benefit more from PIM-side computation.","links":{"pdf":"https://grc.iit.edu/papers/2021/yan-2021-copim-a500.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lu2020apac","slug":"lu-2020-apac-66b5","title":"APAC: An Accurate and Adaptive Prefetch Framework with Concurrent Memory Access Analysis","authors":["X. Lu","R. Wang","X.-H. Sun"],"venue":"The 38th IEEE International Conference on Computer Design (ICCD\'20), October 18 - 21, 2020","type":"Conference","entryType":"inproceedings","date":"October, 2020","year":2020,"era":"iit","month":10,"doi":"10.1109/iccd50377.2020.00048","abstract":"Prefetching techniques have been studied for decades. However, there are few studies on how concurrent memory accesses may affect prefetching effectiveness. When there are multiple concurrent memory requests, we can classify them into sub-classes by analyzing the overlapping relationship. In this work, we first propose pure prefetch coverage (PPC), a novel prefetching metric that can identify an accurate prefetch coverage under the concurrent memory access model. Then we propose APAC, an adaptive prefetch framework with PPC metric that can capture the dynamics of applications and adjust the prefetching aggressiveness. Our experimental results show that the PPC metric has a higher IPC correlation compared to the conventional prefetch coverage (PC) metric. For memory- intensive single-thread benchmarks, APAC provides an average performance improvement by 17.3% and 5.9% compared to the state-of-the-art adaptive prefetch framework FDP and NST. In a multi-core system, APAC outperforms FDP and NST by 8.5% and 5.0% IPC on average, respectively.","hasAbstract":true,"lede":"We first propose pure prefetch coverage (PPC), a novel prefetching metric that can identify an accurate prefetch coverage under the concurrent memory access model.","links":{"pdf":"https://grc.iit.edu/papers/2020/lu-2020-apac-66b5.pdf"},"tags":["Prefetch","Memory Performance Model","Concurrent Memory Access","Optimization of Memory Architectures"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CCF-2008907","agencyKnown":true},{"agency":"NSF","award":"CNS-1730488","agencyKnown":true},{"agency":"NSF","award":"CCF-1536079","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);